/* siege_map.insertSiegeMapSnapshot */
INSERT INTO siege_map_snapshot (
       match_id, captured_at, war_rest_start_time, war_rest_finish_time,
       max_match_score, max_deck_count_per_member, max_attack_unit_count, source
) VALUES (
       #{match_id}, #{captured_at}, #{war_rest_start_time}, #{war_rest_finish_time},
       #{max_match_score}, #{max_deck_count_per_member}, #{max_attack_unit_count}, #{source}
)
ON CONFLICT (match_id, captured_at) DO NOTHING

/* siege_map.insertSiegeMapSnapshotGuildBatch */
INSERT INTO siege_map_snapshot_guild (
       snapshot_id, guild_id, pos_id, guild_name, match_score, match_score_increment,
       match_rank, play_member_count, attack_count, attack_unit_count, disqualified
) VALUES

(
       #{r.snapshot_id}, #{r.guild_id}, #{r.pos_id}, #{r.guild_name}, #{r.match_score},
       #{r.match_score_increment}, #{r.match_rank}, #{r.play_member_count},
       #{r.attack_count}, #{r.attack_unit_count}, #{r.disqualified}
)

/* siege_map.insertSiegeMapSnapshotBaseBatch */
INSERT INTO siege_map_snapshot_base (
       snapshot_id, base_number, base_type, guild_id, base_status,
       battle_start_time, construct_time
) VALUES

(
       #{r.snapshot_id}, #{r.base_number}, #{r.base_type}, #{r.guild_id}, #{r.base_status},
       #{r.battle_start_time}, #{r.construct_time}
)

mapper.select:
/* siege_map.selectSiegeMapMatchHistory */ SELECT m.match_id, m.siege_id, m.season_yyyymm, m.match_start_time, m.match_finish_time, m.snapshot_count, m.first_snapshot_at, m.last_snapshot_at, g1.guild_name AS guild_name_1, g2.guild_name AS guild_name_2, g3.guild_name AS guild_name_3, g1.guild_id AS guild_id_1, g2.guild_id AS guild_id_2, g3.guild_id AS guild_id_3, g1.match_score AS match_score_1, g2.match_score AS match_score_2, g3.match_score AS match_score_3 FROM siege_map_match m LEFT JOIN LATERAL ( SELECT sg.guild_id, sg.guild_name, sg.match_score FROM siege_map_snapshot s JOIN siege_map_snapshot_guild sg ON sg.snapshot_id = s.id AND sg.pos_id = 1 WHERE s.match_id = m.match_id ORDER BY s.captured_at DESC LIMIT 1 ) g1 ON TRUE LEFT JOIN LATERAL ( SELECT sg.guild_id, sg.guild_name, sg.match_score FROM siege_map_snapshot s JOIN siege_map_snapshot_guild sg ON sg.snapshot_id = s.id AND sg.pos_id = 2 WHERE s.match_id = m.match_id ORDER BY s.captured_at DESC LIMIT 1 ) g2 ON TRUE LEFT JOIN LATERAL ( SELECT sg.guild_id, sg.guild_name, sg.match_score FROM siege_map_snapshot s JOIN siege_map_snapshot_guild sg ON sg.snapshot_id = s.id AND sg.pos_id = 3 WHERE s.match_id = m.match_id ORDER BY s.captured_at DESC LIMIT 1 ) g3 ON TRUE WHERE EXISTS ( SELECT 1 FROM siege_map_snapshot s2 JOIN siege_map_snapshot_guild sg2 ON sg2.snapshot_id = s2.id WHERE s2.match_id = m.match_id
AND sg2.guild_id = #{sess_guild_id}::text
) ORDER BY m.last_snapshot_at DESC NULLS LAST, m.match_id DESC LIMIT #{limit} OFFSET #{offset}

/* siege_map.selectSiegeMapMatchHistoryCount */ SELECT COUNT(*)::int FROM siege_map_match m WHERE EXISTS ( SELECT 1 FROM siege_map_snapshot s2 JOIN siege_map_snapshot_guild sg2 ON sg2.snapshot_id = s2.id WHERE s2.match_id = m.match_id
AND sg2.guild_id = #{sess_guild_id}::text
)

/* siege_map.selectSiegeMapMatchById */
SELECT match_id, siege_id, season_yyyymm, rating_id, match_type,
       match_start_time, match_finish_time, snapshot_count,
       first_snapshot_at, last_snapshot_at
  FROM siege_map_match
 WHERE match_id = #{match_id}

/* siege_map.selectSnapshotHeaderById */
SELECT id, match_id, captured_at, war_rest_start_time, war_rest_finish_time,
       max_match_score, max_deck_count_per_member, max_attack_unit_count, source
  FROM siege_map_snapshot
 WHERE id = #{snapshot_id}

/* siege_map.selectSnapshotGuilds */
SELECT guild_id, pos_id, guild_name, match_score, match_score_increment,
       match_rank, play_member_count, attack_count, attack_unit_count, disqualified
  FROM siege_map_snapshot_guild
 WHERE snapshot_id = #{snapshot_id}
 ORDER BY pos_id

/* siege_map.selectSnapshotBases */
SELECT base_number, base_type, guild_id, base_status,
       battle_start_time, construct_time
  FROM siege_map_snapshot_base
 WHERE snapshot_id = #{snapshot_id}
 ORDER BY base_number

/* siege_map.selectSnapshotIdByMatchAndCaptured */
SELECT id
  FROM siege_map_snapshot
 WHERE match_id = #{match_id}
   AND captured_at = #{captured_at}
 LIMIT 1

/* siege_map.selectSnapshotTimeline */
SELECT id, captured_at
  FROM siege_map_snapshot
 WHERE match_id = #{match_id}
 ORDER BY captured_at ASC
 LIMIT 2000

/* siege_map.selectLatestBaseDefenseCapture */
SELECT id,
       match_id,
       base_number,
       captured_at,
       matchup_snapshot_id
  FROM siege_map_base_defense_capture
 WHERE match_id = #{match_id}
   AND base_number = #{base_number}

   AND captured_at <= #{captured_at_max}

 ORDER BY captured_at DESC
 LIMIT 1
